 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The stamp is the unique horizontal run of five non-background cells.
    stamp_pos = None
    for r, row in enumerate(grid):
        for c in range(w - 4):
            if all(row[j] != bg for j in range(c, c + 5)):
                stamp_pos = (r, c)
                break
        if stamp_pos:
            break
    if stamp_pos is None:
        raise ValueError('five-cell stamp not found')
    sr, sc = stamp_pos
    stamp = grid[sr][sc:sc + 5]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if (r, c) == (sr, sc):
                continue
            # Find isolated foreground cells outside the stamp, including any
            # same-color cells that form part of the stamp elsewhere.
            if grid[r][c] == bg or (r == sr and sc <= c < sc + 5):
                continue
            # Each marker is a singleton (all other foreground cells belong to stamp).
            out[r][c] = bg
            start = c - 2
            for k, color in enumerate(stamp):
                if 0 <= start + k < w:
                    out[r][start + k] = color
    return out
